 const courseCard=(c,label)=>`<article class="card"><div class="card-body"><span class="tag">${esc(c.level)} • ${esc(c.category)}</span><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><div class="progress" role="progressbar" aria-label="Progresso de ${esc(c.name)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${c.percent}"><span style="width:${c.percent}%"></span></div><p class="small">${c.done}/${c.total} aulas • ${c.percent}%</p><a class="card-link" href="/curso/${encodeURIComponent(c.id)}">${label} →</a></div></article>`;
 content.innerHTML=`<section class="hero ce-dashboard-hero"><span class="eyebrow">✦ SUA JORNADA</span><h1>${hasProgress?'Olá, '+esc((d.name||'').split(' ')[0])+'!':'Comece sua jornada na tecnologia'}</h1><p>${hasProgress?'Acompanhe seus estudos e conquistas.':'Escolha seu primeiro curso e comece a aprender.'}</p><a class="btn dark-btn" href="/cursos">Explorar cursos ↗</a></section>
 <section aria-label="Seu desempenho"><div class="section-title"><h2>Seu desempenho</h2></div><div class="stats">${summary.map(([label,value])=>`<div class="stat"><div><small>${label}</small><strong>${value}</strong></div></div>`).join('')}</div><p class="small">${d.completed_lessons} de ${d.total_lessons} aulas concluídas no catálogo.</p></section>
 <section class="ce-dashboard-insights"><article class="panel"><div class="section-title"><h2>Ritmo de estudos</h2><span class="small">Últimos 7 dias</span></div>${weekChart}<p class="small">${days.reduce((n,x)=>n+x.count,0)} aulas concluídas nesta semana móvel.</p></article><article class="panel ce-learning-summary"><h2>Seu aprendizado</h2><div class="ce-ring" style="--pct:${Math.max(0,Math.min(100,d.progress))}%"><strong>${d.progress}%</strong><small>do catálogo</small></div><p>${d.completed_lessons} aulas concluídas</p><a href="/perfil">Ver desempenho completo →</a></article></section>
 <section class="ce-shortcuts" aria-label="Acesso rápido">${[['/trilha-personalizada','Sua trilha','Organize seu caminho'],['/lia','LIA','Tire dúvidas'],['/laboratorio','Laboratório','Pratique código'],['/oportunidades','Oportunidades','Explore vagas']].map(([url,title,desc])=>`<a class="panel" href="${url}"><strong>${title} ↗</strong><small>${desc}</small></a>`).join('')}</section>
 ${!hasProgress?`<section class="panel"><h2>Seu primeiro passo</h2><p>Você ainda não iniciou nenhum curso. Explore nossas trilhas.</p><a class="btn" href="/cursos">Explorar cursos</a></section>`:''}
 ${d.started.length?`<section><div class="section-title"><h2>Continuar aprendendo</h2><a href="/cursos">Ver cursos →</a></div><div class="grid">${d.started.map(c=>courseCard(c,'Continuar curso')).join('')}</div></section>`:''}
 ${d.finished.length?`<section><div class="section-title"><h2>Cursos concluídos</h2></div><div class="grid">${d.finished.map(c=>courseCard(c,'Revisar curso')).join('')}</div></section>`:''}
 ${d.recommendations.length?`<section><div class="section-title"><h2>Recomendados para você</h2></div><div class="grid">${d.recommendations.map(c=>courseCard(c,'Conhecer curso')).join('')}</div></section>`:''}
 ${d.recent.length?`<section class="panel"><h2>Atividades recentes</h2><ul>${d.recent.map(a=>`<li><strong>${esc(a.title)}</strong><p class="small">${esc(a.course)} • ${esc(a.date)}</p></li>`).join('')}</ul></section>`:''}`;
