function drawBars(canvas,values,labels,max){const ctx=canvas.getContext('2d'),dpr=window.devicePixelRatio||1,w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;canvas.width=w*dpr;canvas.height=h*dpr;ctx.scale(dpr,dpr);const css=getComputedStyle(document.body),accent=css.getPropertyValue('--accent').trim()||'#7b32ef',muted=css.getPropertyValue('--muted').trim(),border=css.getPropertyValue('--border').trim();const left=38,right=12,top=20,bottom=42,plot=h-top-bottom,step=(w-left-right)/Math.max(values.length,1);ctx.font='11px system-ui';ctx.textAlign='right';for(let i=0;i<=4;i++){const y=top+plot*i/4;ctx.strokeStyle=border;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(w-right,y);ctx.stroke();ctx.fillStyle=muted;ctx.fillText(String(Math.round(max*(1-i/4))),left-6,y+4)}ctx.textAlign='center';values.forEach((v,i)=>{const bh=plot*Math.min(1,v/Math.max(1,max)),bw=Math.min(35,step*.65),x=left+step*(i+.5),y=top+plot-bh;ctx.fillStyle=accent;if(bh>0){ctx.beginPath();ctx.roundRect(x-bw/2,y,bw,bh,Math.min(6,bh/2));ctx.fill()}ctx.fillStyle=muted;ctx.fillText(String(v),x,Math.max(12,y-5));ctx.fillText(String(labels[i]).slice(0,Math.max(3,Math.floor(step/7))),x,h-20)});if(!values.length){ctx.fillStyle=muted;ctx.fillText('Nenhuma atividade registrada',w/2,h/2)}}
function drawCharts(){if(!$('#chart-courses')||!$('#chart-activity')||$('#profile-learning')?.hidden)return;let courses=stats.per_course.filter(x=>x.done>0).slice(0,7);if(!courses.length)courses=stats.per_course.slice(0,6);drawBars($('#chart-courses'),courses.map(x=>Math.round(x.done/x.total*100)),courses.map(x=>x.name),100);$('#chart-table').textContent=courses.map(x=>`${x.name}: ${x.done}/${x.total}`).join(' • ');let a=stats.activity;drawBars($('#chart-activity'),a.map(x=>x.count),a.map(x=>x.date.slice(5)),Math.max(1,...a.map(x=>x.count)));window.onresize=()=>{if(page==='profile')drawCharts()}}
async function certificatesPage(){let rows=await api('/data/certificates');content.innerHTML=heading('SUAS CONQUISTAS','Certificados digitais','Documentos de conclusão com autenticação pública e PDF para impressão.')+`<div class="panel cert-preview"><span class="tag">CONECTAS ELAS</span><h2>Certificado profissional de conclusão</h2><p>Conclua todas as aulas e seja aprovada nas avaliações de cada módulo para receber o certificado automaticamente.</p><span class="small">Documento com código único de autenticidade.</span></div><div class="section-title"><h2>Meus certificados (${rows.length})</h2></div><div class="certificate-list">${rows.length?rows.map(r=>`<article class="panel"><span class="tag">CERTIFICADO EMITIDO</span><h3>${esc(r.course_name)}</h3><p>${esc(r.hours)} horas estimadas • Conclusão: ${esc(r.issued_at.slice(0,10))}</p><p class="small">Código: <code>${esc(r.code)}</code></p><div class="row"><a class="btn" href="/certificado/pdf/${encodeURIComponent(r.code)}">↓ Baixar PDF</a><a class="btn secondary" href="/certificado/pdf/${encodeURIComponent(r.code)}?imprimir=1" target="_blank" rel="noopener">Imprimir PDF</a><a class="btn secondary" href="/certificado/verificar/${encodeURIComponent(r.code)}">Verificar autenticidade</a></div></article>`).join(''):'<div class="ce-empty-state"><h3>Seu primeiro certificado está a caminho</h3><p>Conclua um curso e suas avaliações para receber o certificado automaticamente.</p><a class="btn" href="/cursos">Explorar cursos</a></div>'}</div>`}
