  $('#jobs-clear')?.addEventListener('click',()=>savedOnly?select('all'):(['job-query','job-location'].forEach(id=>$('#'+id).value=''),['job-category','job-mode'].forEach(id=>$('#'+id).value=''),cards(false)));
