async function plannerPage(){let catalog=await api('/api/catalogo');let saved=null;try{saved=(await api('/data/plan')).plan}catch(e){}const goals=Object.entries(catalog.tracks);content.innerHTML=heading('SEU CAMINHO • PERSONALIZADO','Sua trilha de aprendizagem','Monte uma jornada real, salve no banco de dados e continue exatamente de onde parou.')+`<div class="planner-hero"><div><span class="planner-eyebrow">✦ APRENDIZAGEM INTELIGENTE</span><h2>Um caminho criado para seus objetivos.</h2><p>Escolha o que deseja aprender. Nós organizamos os cursos em ordem, dividimos suas aulas por semana e acompanhamos cada conquista.</p></div><div class="planner-orbit" aria-hidden="true"><span>⌘</span><span>✧</span><span>◇</span></div></div><div class="planner-form panel"><div class="planner-form-heading"><div><span class="tag">PASSO 01</span><h2>Personalize seu plano</h2></div><span class="planner-step">01 / 03</span></div><div class="planner-input-grid"><label class="label">Qual é seu objetivo?<select class="field" id="goal">${goals.map(([id,t])=>`<option value="${esc(id)}">${esc(t.label||id)}</option>`).join('')}</select></label><label class="label">Seu nível<select class="field" id="level"><option value="iniciante">Iniciante</option><option value="intermediario">Intermediário</option><option value="avancado">Avançado</option></select></label><label class="label">Tempo disponível por semana<input id="hours" class="field" type="number" min="1" max="40" value="5" aria-describedby="hours-help"><small id="hours-help">De 1 a 40 horas por semana</small></label></div><button class="btn" id="plan">✦ Gerar minha trilha</button></div><div id="saved-plan" aria-live="polite"></div><div id="plan-results" aria-live="polite"></div>`;let goal=$('#goal'),level=$('#level'),hours=$('#hours');if(saved){goal.value=goals.some(([k])=>k===saved.goal)?saved.goal:goal.value;level.value=saved.level;hours.value=saved.hours_per_week;renderSaved(saved)}$('#plan').onclick=async()=>{if(loginNeeded())return;const h=Number(hours.value);if(!Number.isInteger(h)||h<1||h>40)return msg('Informe entre 1 e 40 horas de estudo por semana.');const b=$('#plan');b.disabled=true;b.textContent='Preparando sua trilha...';try{const x=await api('/api/trilha','POST',{objetivos:[goal.value],nivel:level.value,horas_semana:h});if(!x.course_ids?.length)throw Error('Nenhum curso disponível para este objetivo.');const result=await api('/data/plan','POST',{course_ids:x.course_ids,goal:goal.value,level:level.value,hours_per_week:h});saved=result.plan;renderSaved(saved);msg('Trilha salva no banco de dados! Seu progresso será atualizado quando concluir as aulas.')}catch(e){fail(e)}finally{b.disabled=false;b.textContent='✦ Gerar minha trilha'}};function renderSaved(p){const allDone=p.done===p.total;const next=p.next;const courses=p.courses;$('#saved-plan').innerHTML=`<section class="plan-dashboard"><div class="planner-form-heading"><div><span class="tag">PASSO 02 • SUA TRILHA ATIVA</span><h2>Meu roteiro de estudos</h2><p>Seu plano fica salvo na sua conta, mesmo depois de sair e entrar novamente.</p></div><button class="btn ghost" id="remove-plan">Excluir plano</button></div><div class="plan-kpis"><div><span>PROGRESSO TOTAL</span><strong>${p.percent}%</strong></div><div><span>AULAS CONCLUÍDAS</span><strong>${p.done}<small> / ${p.total}</small></strong></div><div><span>RITMO DE ESTUDO</span><strong>${p.hours_per_week}h <small>/ semana</small></strong></div><div><span>SEMANAS RESTANTES</span><strong>${p.estimated_weeks}</strong></div></div><div class="plan-progress" role="progressbar" aria-valuenow="${p.percent}" aria-valuemin="0" aria-valuemax="100" aria-label="Progresso da trilha"><span style="width:${p.percent}%"></span></div>${next?`<div class="next-up"><div><span class="tag">▶ CONTINUE DE ONDE PAROU</span><h3>${esc(next.title)}</h3><p>${esc(next.course_name)} • ${esc(next.module)}</p></div><a class="btn" href="/curso/${encodeURIComponent(next.course_id)}?aula=${encodeURIComponent(next.id)}">Continuar estudando →</a></div>`:`<div class="next-up"><h3>🎉 Você concluiu sua trilha!</h3><a class="btn" href="/certificados">Ver certificados →</a></div>`}</section><section class="plan-section"><div class="planner-form-heading"><div><span class="tag">PASSO 03 • CURSOS ORGANIZADOS</span><h2>Sua jornada, etapa por etapa</h2></div><span class="planner-step">${courses.length} cursos</span></div><div class="ce-visual-road">${courses.map((c,i)=>{const state=c.done===c.total?'done':i===courses.findIndex(x=>x.done<x.total)?'ready':'locked';return `<article class="ce-road-step ${state}"><div class="ce-road-node" aria-hidden="true">${state==='done'?'✓':state==='ready'?'▶':'🔒'}</div><h3>${esc(c.name)}</h3><p class="small">${c.done}/${c.total} aulas · ${c.percent}%</p>${state==='locked'?'<span class="small">Conclua a etapa anterior</span>':`<a class="btn ${state==='done'?'secondary':''}" href="/curso/${encodeURIComponent(c.id)}${c.next_lesson?'?aula='+encodeURIComponent(c.next_lesson):''}">${state==='done'?'Revisar':'Continuar'}</a>`}</article>`}).join('')}</div></section><section class="plan-section"><div class="planner-form-heading"><div><span class="tag">ORGANIZAÇÃO SEMANAL</span><h2>Seu cronograma de estudos</h2><p>35 minutos por aula e 15 minutos por revisão. O cronograma respeita suas horas disponíveis e se ajusta ao seu progresso.</p></div></div><div class="panel"><h3>Revisão das suas dificuldades</h3><p class="small">Prioridade para aulas com erros ainda não superados. Reserve parte das suas horas semanais para estas revisões.</p>${(p.reviews||[]).map(r=>`<p><a class="link" href="/curso/${encodeURIComponent(r.course_id)}?aula=${encodeURIComponent(r.id)}">${esc(r.title)}</a> · ${r.errors} erro(s) · revisão sugerida de 15 min</p>`).join('')||'<p>Nenhuma dificuldade identificada pelas tentativas até agora.</p>'}</div><div class="week-grid">${p.weeks.map(w=>`<details class="week-card" ${w.number===1?'open':''}><summary><span>SEMANA ${String(w.number).padStart(2,'0')}</span><strong>${w.count} aulas • ${Math.round(w.minutes/60*10)/10}h</strong></summary><ol>${w.lessons.map(l=>`<li><a href="/curso/${encodeURIComponent(l.course_id)}?aula=${encodeURIComponent(l.id)}">${l.review?'Revisar: ':''}${esc(l.title)}</a><small>${esc(l.course_name)} · ${l.minutes||35} min</small></li>`).join('')}</ol></details>`).join('')||'<p class="empty">Todas as atividades foram concluídas!</p>'}</div>${p.estimated_weeks>8?`<p class="small">Mostrando as próximas 8 semanas. Ao concluir aulas, o cronograma será atualizado.</p>`:''}</section>`;$('#remove-plan').onclick=async()=>{if(!confirm('Deseja excluir sua trilha personalizada? Seu progresso nos cursos será mantido.'))return;try{await api('/data/plan','DELETE');$('#saved-plan').innerHTML='';msg('Trilha excluída. Suas aulas concluídas continuam salvas.')}catch(e){fail(e)}}}}
