async function renderPerformance(){
 const p=await api('/data/performance');const el=document.createElement('section');el.className='performance-section';
 const bars=(items,labelKey,valueKey,max)=>`<div class="perf-bars">${items.map(x=>`<div class="perf-bar"><span>${esc(x[labelKey])}</span><div class="perf-track"><i style="width:${Math.min(100,Math.round(100*x[valueKey]/Math.max(1,max)))}%"></i></div><strong>${x[valueKey]}</strong></div>`).join('')}</div>`;
 el.innerHTML=`<h2>Meu painel de conquistas</h2><div class="perf-kpis">${[['Cursos iniciados',p.courses_started],['Cursos concluídos',p.courses_completed],['XP conquistado',p.xp],['Nível',p.level],['Dias seguidos',p.streak],['Respostas corretas',p.correct],['Respostas incorretas',p.incorrect]].map(([k,v])=>`<div class="panel"><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><div class="chart-row"><div class="panel"><h3>Evolução semanal</h3>${bars(p.weekly.map(x=>({...x,label:x.date.slice(5)})),'label','count',Math.max(1,...p.weekly.map(x=>x.count)))}</div><div class="panel"><h3>Evolução mensal</h3>${bars(p.monthly,'month','count',Math.max(1,...p.monthly.map(x=>x.count)))}</div></div><div class="panel"><h3>Desempenho por linguagem ou curso</h3>${p.languages.length?bars(p.languages,'name','percent',100):'<p>Conclua uma aula para visualizar seu desempenho.</p>'}<p class="small">Os percentuais mostram aulas concluídas, não notas.</p></div><div class="chart-row"><div class="panel"><h3>Minha meta semanal</h3><p>${p.weekly_done} de ${p.weekly_goal} aulas concluídas nesta semana</p><div class="perf-track"><i style="width:${Math.min(100,Math.round(p.weekly_done/p.weekly_goal*100))}%"></i></div><form id="weekly-goal-form"><label class="label">Aulas por semana <input class="field" id="weekly-goal" type="number" min="1" max="100" value="${p.weekly_goal}" required></label><button class="btn">Salvar meta</button></form></div><div class="panel"><h3>Conquistas</h3>${p.achievements.map(x=>`<p>${x.unlocked?'🏆':'🔒'} ${esc(x.name)}</p>`).join('')}</div></div><div class="panel"><h3>Certificados conquistados</h3>${p.certificates.length?p.certificates.map(x=>`<p>${esc(x.name)} · <a href="/certificado/pdf/${encodeURIComponent(x.code)}">Ver certificado</a></p>`).join(''):'<p>Você ainda não emitiu certificados.</p>'}</div>`;
 const destination=document.querySelector('#profile-learning')||content;destination.querySelector('.performance-section')?.remove();destination.appendChild(el);$('#weekly-goal-form').onsubmit=async e=>{e.preventDefault();try{await api('/data/performance/goal','POST',{target:Number($('#weekly-goal').value)});msg('Meta semanal salva!');el.remove();await renderPerformance()}catch(err){fail(err)}};
}

function applyAccessibleFont(){const saved=Number(localStorage.getItem('ce-size')||16);const n=Number.isFinite(saved)?Math.max(12,Math.min(24,saved)):16;document.documentElement.style.setProperty('--user-font-scale',String(n/16));document.documentElement.style.fontSize=n+'px';}
function announceAccess(message){let region=document.getElementById('access-announcement');if(!region){region=document.createElement('div');region.id='access-announcement';region.className='sr-only';region.setAttribute('role','status');region.setAttribute('aria-live','polite');document.body.appendChild(region)}region.textContent='';requestAnimationFrame(()=>region.textContent=message)}
function updateAccessControls(){const dark=document.body.classList.contains('dark'),contrast=document.body.classList.contains('contrast'),reduced=document.body.classList.contains('reduce-motion');const set=(id,on,label)=>{let b=document.getElementById(id);if(b){b.setAttribute('aria-pressed',String(on));b.setAttribute('aria-label',label)}};set('theme',dark,'Tema escuro '+(dark?'ativado':'desativado')+', alternar tema');set('contrast',contrast,'Alto contraste '+(contrast?'ativado':'desativado')+', alternar');set('motion',reduced,'Redução de animações '+(reduced?'ativada':'desativada')+', alternar');}
async function start(){let nav=page==='course'?'courses':page==='verify'?'certificates':page;$$('[data-nav]').forEach(x=>(x.classList.toggle('active',x.dataset.nav===nav),x.dataset.nav===nav?x.setAttribute('aria-current','page'):x.removeAttribute('aria-current')));document.body.classList.toggle('dark',localStorage.getItem('ce-theme')==='dark');document.body.classList.toggle('contrast',localStorage.getItem('ce-contrast')==='1');document.body.classList.toggle('reduce-motion',localStorage.getItem('ce-motion')==='1');applyAccessibleFont();updateAccessControls();$('#theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('ce-theme',document.body.classList.contains('dark')?'dark':'light');updateAccessControls();if(page==='profile')drawCharts()};$('#contrast').onclick=()=>{document.body.classList.toggle('contrast');localStorage.setItem('ce-contrast',document.body.classList.contains('contrast')?'1':'0');updateAccessControls();if(page==='profile')drawCharts()};function size(d){let n=Math.max(12,Math.min(24,Number(localStorage.getItem('ce-size')||16)+d*2));localStorage.setItem('ce-size',String(n));applyAccessibleFont();announceAccess('Tamanho do texto: '+Math.round(n/16*100)+' por cento')}$('#font-plus').onclick=()=>size(1);$('#font-minus').onclick=()=>size(-1);$('#motion').onclick=()=>{let reduced=!document.body.classList.contains('reduce-motion');document.body.classList.toggle('reduce-motion',reduced);localStorage.setItem('ce-motion',reduced?'1':'0');updateAccessControls();announceAccess(reduced?'Animações reduzidas':'Animações habilitadas')};$('#search').addEventListener('input',search);$('#search').addEventListener('keydown',e=>{if(e.key==='Enter'&&page!=='courses')location.href='/cursos'});try{await refresh();const notice=sessionStorage.getItem('ce-verification-notice');if(notice){sessionStorage.removeItem('ce-verification-notice');msg(notice)}if(me?.account_type==='company'&&page!=='auth'&&page!=='verify'&&page!=='admin'){await businessPage();return;}let fn={professionalchat:professionalChatPage,dashboard,courses:coursesPage,course:coursePage,profile:profilePage,certificates:certificatesPage,verify:verifyPage,jobs:jobsPage,jobdetail:jobDetailPage,portfolio:portfolioPage,publicportfolio:publicPortfolioPage,community:communityPage,admin:adminPage,auth:authPage,lab:labPage,tutor:tutorPage,planner:plannerPage,projects:projectsPage,challenges:challengesPage}[page];if(fn)await fn();}catch(e){fail(e)}}start();
// Interface responsiva e notificações da etapa 1
(function(){
 const toggle=document.getElementById('menu-toggle'), overlay=document.getElementById('mobile-overlay'), sidebar=document.getElementById('site-sidebar');
 if(!toggle||!overlay||!sidebar)return;
 const close=()=>{document.body.classList.remove('menu-open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Abrir menu');overlay.hidden=true;if(document.activeElement&&sidebar.contains(document.activeElement))toggle.focus()};
 toggle.addEventListener('click',()=>{const open=!document.body.classList.contains('menu-open');document.body.classList.toggle('menu-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');overlay.hidden=!open;if(open){const first=sidebar.querySelector('a');if(first)first.focus()}else toggle.focus()});
 overlay.addEventListener('click',close);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('menu-open'))close();if(e.key==='Tab'&&document.body.classList.contains('menu-open')){const items=[...sidebar.querySelectorAll('a,button,[tabindex]:not([tabindex="-1"])')].filter(x=>!x.disabled);if(items.length){const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}});
 sidebar.querySelectorAll('a').forEach(a=>a.addEventListener('click',close));
 document.querySelectorAll('.sidebar a.active').forEach(a=>a.setAttribute('aria-current','page'));
 const flash=document.getElementById('flash'), region=document.getElementById('toast-region');
 if(flash&&region){const observer=new MutationObserver(()=>{if(flash.hidden||!flash.textContent.trim())return;const toast=document.createElement('div');toast.className='toast';toast.textContent=flash.textContent.trim();region.replaceChildren(toast);setTimeout(()=>toast.remove(),4500)});observer.observe(flash,{attributes:true,childList:true,characterData:true,subtree:true})}
})();

async function adminPage(){
 content.innerHTML=heading('GESTÃO SEGURA','Painel administrativo','Acesso exclusivo a administradores autorizados.')+'<div class="panel" id="admin-body">Verificando permissões...</div>';
 try{await api('/data/admin/access')}catch(e){$('#admin-body').textContent=e.message;return}
 const root=$('#admin-body');root.innerHTML='<div class="row"><button class="btn" data-tab="overview">Visão geral</button><button class="btn secondary" data-tab="courses">Cursos e aulas</button><button class="btn secondary" data-tab="jobs">Oportunidades</button><button class="btn secondary" data-tab="moderation">Moderação</button><button class="btn secondary" data-tab="certificates">Certificados</button></div><div id="admin-section" style="margin-top:24px"></div>';
 const area=$('#admin-section');let courseCache=[];
 async function tab(name){try{
  if(name==='overview'){let x=await api('/data/admin/overview');area.innerHTML='<h2>Indicadores reais do SQL</h2><div class="perf-kpis">'+[['Alunas cadastradas',x.users],['Alunas com aulas concluídas',x.active_students],['Cursos',x.courses],['Certificados emitidos',x.certificates],['Conclusões / alunas × cursos',x.completion_rate+'%'],['Denúncias pendentes',x.reports]].map(([k,v])=>`<div class="panel"><small>${esc(k)}</small><h2>${esc(v)}</h2></div>`).join('')+'</div><h3>Cursos mais acessados</h3>'+(x.views.map(v=>`<p>${esc(v.name)}: ${v.views} acessos</p>`).join('')||'<p>Ainda sem acessos registrados.</p>')+'<h3>Questões com mais erros</h3>'+(x.difficulties.map(v=>`<p>${esc(v.lesson_id)}: ${v.errors} erros</p>`).join('')||'<p>Sem erros registrados.</p>');}
  if(name==='courses'){courseCache=await api('/data/admin/courses');area.innerHTML='<h2>Gerenciar cursos e aulas</h2><label>Curso <select id="adm-course" class="field"><option value="">Novo curso</option>'+courseCache.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')+'</select></label><form id="adm-course-form" class="admin-form"><label>ID <input class="field" name="id" required></label><label>Nome <input class="field" name="name" required></label><label>Descrição <textarea class="field" name="description"></textarea></label><label>Categoria <input class="field" name="category"></label><label>Nível <select class="field" name="level"><option>Iniciante</option><option>Intermediário</option><option>Avançado</option></select></label><label>Carga horária <input class="field" type="number" min="0" name="hours"></label><button class="btn">Salvar curso</button></form><h3>Adicionar ou editar aula / avaliação</h3><label>Aula <select class="field" id="adm-lesson"><option value="">Nova aula</option></select></label><form id="adm-lesson-form" class="admin-form"><label>ID (deixe vazio para gerar) <input class="field" name="id"></label><label>Módulo <input class="field" name="module" required></label><label>Título <input class="field" name="title" required></label><label>Explicação <textarea class="field" name="body"></textarea></label><label>Exercício <textarea class="field" name="practice"></textarea></label><label>Projeto / desafio <textarea class="field" name="challenge"></textarea></label><label>Pergunta <input class="field" name="question"></label><label>Alternativas (uma por linha) <textarea class="field" name="options" required></textarea></label><label>Alternativa correta (1 a 6) <input class="field" type="number" name="answer" min="1" max="6" required></label><label>Explicação da resposta <textarea class="field" name="explanation"></textarea></label><button class="btn">Salvar aula e avaliação</button></form>';
 const cs=$('#adm-course'),cf=$('#adm-course-form'),ls=$('#adm-lesson'),lf=$('#adm-lesson-form');cs.onchange=()=>{let c=courseCache.find(x=>x.id===cs.value);cf.reset();if(c)for(let [k,v] of Object.entries(c)){if(cf.elements.namedItem(k))cf.elements.namedItem(k).value=v}cf.elements.namedItem('id').readOnly=!!c;ls.innerHTML='<option value="">Nova aula</option>'+(c?.lessons||[]).map(l=>`<option value="${esc(l.id)}">${esc(l.title)}</option>`).join('');lf.reset()};ls.onchange=()=>{lf.reset();let c=courseCache.find(x=>x.id===cs.value),l=c?.lessons.find(x=>x.id===ls.value);if(l){for(let k of ['id','module','title','body','practice','challenge','question','explanation'])lf.elements.namedItem(k).value=l[k]||'';lf.elements.namedItem('options').value=(l.options||[]).join('\n');lf.elements.namedItem('answer').value=(l.answer||0)+1}};
 cf.onsubmit=async e=>{e.preventDefault();try{let x=Object.fromEntries(new FormData(cf));await api('/data/admin/courses','POST',x);msg('Curso salvo.');await tab('courses')}catch(err){fail(err)}};
 lf.onsubmit=async e=>{e.preventDefault();if(!cs.value)return msg('Selecione e salve um curso antes.');let x=Object.fromEntries(new FormData(lf));x.options=x.options.split('\n').map(s=>s.trim()).filter(Boolean);x.answer=Number(x.answer)-1;try{await api('/data/admin/courses/'+encodeURIComponent(cs.value)+'/lessons','POST',x);msg('Aula e avaliação salvas.');await tab('courses')}catch(err){fail(err)}};
  }
  if(name==='jobs'){let jobs=await api('/data/admin/jobs');area.innerHTML='<h2>Gerenciar oportunidades</h2><label>Editar <select class="field" id="adm-job"><option value="">Nova oportunidade</option>'+jobs.map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('')+'</select></label><form id="adm-job-form" class="admin-form">'+[['title','Título'],['organization','Organização'],['mode','Modalidade'],['category','Categoria'],['salary','Salário ou faixa salarial']].map(([k,v])=>`<label>${v}<input class="field" name="${k}" required></label>`).join('')+'<label>Descrição<textarea class="field" name="description"></textarea></label><button class="btn">Salvar oportunidade</button></form><p class="small">Oportunidades são demonstrativas; não publicar vagas reais sem fonte verificada.</p>';let select=$('#adm-job'),form=$('#adm-job-form');select.onchange=()=>{form.reset();let x=jobs.find(j=>j.id===Number(select.value));if(x)for(let k of ['title','organization','mode','category','description','salary'])form.elements.namedItem(k).value=x[k]};form.onsubmit=async e=>{e.preventDefault();try{await api('/data/admin/jobs','POST',{...Object.fromEntries(new FormData(form)),id:Number(select.value)||null});msg('Oportunidade salva.');await tab('jobs')}catch(err){fail(err)}}}
  if(name==='moderation'){let rows=await api('/data/community/moderation');area.innerHTML='<h2>Denúncias pendentes</h2>'+(rows.map(r=>`<article class="panel"><p>${esc(r.reason)}</p><small>Publicação ${esc(r.post_id||'-')} • Comentário ${esc(r.comment_id||'-')}</small><div class="row"><button class="btn" data-mod="hide" data-id="${r.id}">Ocultar conteúdo</button><button class="btn secondary" data-mod="dismiss" data-id="${r.id}">Dispensar</button></div></article>`).join('')||'<p>Não há denúncias pendentes.</p>');$$('[data-mod]').forEach(b=>b.onclick=async()=>{try{await api('/data/community/moderation/'+b.dataset.id,'POST',{action:b.dataset.mod});await tab('moderation')}catch(e){fail(e)}})}
  if(name==='certificates'){let rows=await api('/data/admin/certificates');area.innerHTML='<h2>Certificados emitidos</h2><p class="small">A emissão é automática somente após aprovação; administradores podem revogar documentos inválidos.</p>'+(rows.map(r=>`<article class="panel"><h3>${esc(r.course_id)}</h3><p>${esc(r.name)} • ${esc(r.issued_at)} • ${esc(r.code)}</p><p>${r.revoked?'Revogado':'Válido'}</p>${r.revoked?'':`<button class="btn secondary" data-revoke="${esc(r.code)}">Revogar</button>`}</article>`).join('')||'<p>Nenhum certificado emitido.</p>');$$('[data-revoke]').forEach(b=>b.onclick=async()=>{let reason=prompt('Motivo da revogação (mínimo 5 caracteres):');if(reason===null)return;try{await api('/data/admin/certificates/'+encodeURIComponent(b.dataset.revoke)+'/revoke','POST',{reason});msg('Certificado revogado.');await tab('certificates')}catch(e){fail(e)}})}
 }catch(e){area.textContent=e.message}}
 $$('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));await tab('overview');
}

// PASSO 13: mídia educativa acessível — legendas e transcrição quando fornecidas.
window.ceAccessibleMedia = function(video, captionsUrl, transcriptText){
  if(!video || video.tagName !== 'VIDEO')return;
  video.controls=true;video.setAttribute('aria-label',video.getAttribute('aria-label')||'Vídeo da aula');
  if(captionsUrl){var track=document.createElement('track');track.kind='captions';track.srclang='pt-BR';track.label='Português';track.src=captionsUrl;track.default=true;video.appendChild(track);}
  if(transcriptText){var details=document.createElement('details');var summary=document.createElement('summary');summary.textContent='Ler transcrição';var text=document.createElement('p');text.textContent=transcriptText;details.append(summary,text);video.insertAdjacentElement('afterend',details);}
};

// Fechar o menu com Escape e atualizar a sessão ao voltar do cache do navegador.
(function(){const menu=document.getElementById('ce-account-menu');if(!menu)return;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.open){menu.open=false;menu.querySelector('summary')?.focus();}});document.addEventListener('click',e=>{if(menu.open&&!menu.contains(e.target))menu.open=false;});window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});})();

